fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if c >= 'a' && c <= 'z' {
                // Convert lowercase ASCII to uppercase
                ((c as u8) - b'a' + b'A') as char
            } else if c >= 'A' && c <= 'Z' {
                // Convert uppercase ASCII to lowercase
                ((c as u8) - b'A' + b'a') as char
            } else {
                // Non-ASCII or non-alphabetic characters remain unchanged
                c
            }
        })
        .collect()
}